const replaceSubscriptions = `-- name: ReplaceSubscriptions :exec
UPDATE app.subscriptions SET status = 'replaced',
  ends_at = CASE WHEN starts_at < now() THEN LEAST(ends_at, now()) ELSE ends_at END
WHERE id = ANY($1::uuid[]) AND status = 'active'
`

// An upgrade ends running lower plans now; queued ones keep their dates and simply never start (status).
func (q *Queries) ReplaceSubscriptions(ctx context.Context, ids []pgtype.UUID) error {
	_, err := q.db.Exec(ctx, replaceSubscriptions, ids)
	return err
}

const searchUsers = `-- name: SearchUsers :many
SELECT u.id, u.username, u.phone_e164, u.first_name, u.last_name, u.email, u.created_at, u.last_seen_at, u.blocked_at,
       coalesce(cur.plan_code, 'free')::text AS current_plan, cur.ends_at AS current_ends_at
FROM app.users u
LEFT JOIN LATERAL (
  SELECT s.plan_code, s.ends_at FROM app.subscriptions s JOIN app.plans p ON p.code = s.plan_code
  WHERE s.user_id = u.id AND s.status = 'active' AND s.starts_at <= now() AND s.ends_at > now()
  ORDER BY p.rank DESC LIMIT 1
) cur ON true
WHERE $1::text = ''
   OR u.username ILIKE '%' || $1::text || '%'
   OR u.phone_e164 ILIKE '%' || $1::text || '%'
   OR (coalesce(u.first_name, '') || ' ' || coalesce(u.last_name, '')) ILIKE '%' || $1::text || '%'
   OR u.id::text LIKE $1::text || '%'
ORDER BY u.last_seen_at DESC
LIMIT 50
`

type SearchUsersRow struct {
	ID            pgtype.UUID
	Username      string
	PhoneE164     pgtype.Text
	FirstName     pgtype.Text
	LastName      pgtype.Text
	Email         pgtype.Text
	CreatedAt     pgtype.Timestamptz
	LastSeenAt    pgtype.Timestamptz
	BlockedAt     pgtype.Timestamptz
	CurrentPlan   string
	CurrentEndsAt pgtype.Timestamptz
}

// Admin search by mobile, name or id prefix, newest first, with the plan they hold now.
func (q *Queries) SearchUsers(ctx context.Context, q_ string) ([]SearchUsersRow, error) {
	rows, err := q.db.Query(ctx, searchUsers, q_)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchUsersRow{}
	for rows.Next() {
		var i SearchUsersRow
		if err := rows.Scan(
			&i.ID,
			&i.Username,
			&i.PhoneE164,
			&i.FirstName,
			&i.LastName,
			&i.Email,
			&i.CreatedAt,
			&i.LastSeenAt,
			&i.BlockedAt,
			&i.CurrentPlan,
			&i.CurrentEndsAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

